<section class="content-header"><h1><i class="fa fa-ban"></i> Reporte de anulaciones</h1></section><section class="content">
<div class="box box-danger no-print"><div class="box-body"><form method="get" class="form-inline"><label>Desde</label> <input type="date" name="desde" class="form-control" value="<?php echo html_escape($filtros['desde']);?>"> <label>Hasta</label> <input type="date" name="hasta" class="form-control" value="<?php echo html_escape($filtros['hasta']);?>"> <select name="ruta_id" class="form-control"><option value="0">Todas las rutas</option><?php foreach($listas['rutas'] as $r):?><option value="<?php echo $r['ruta_id'];?>" <?php echo $filtros['ruta_id']==$r['ruta_id']?'selected':'';?>><?php echo html_escape($r['ruta_nombre']);?></option><?php endforeach;?></select> <select name="vendedor_id" class="form-control"><option value="0">Todos los vendedores</option><?php foreach($listas['usuarios'] as $u):?><option value="<?php echo $u['usuario_id'];?>" <?php echo $filtros['vendedor_id']==$u['usuario_id']?'selected':'';?>>Vende: <?php echo html_escape($u['usuario_nombre']);?></option><?php endforeach;?></select> <select name="anulador_id" class="form-control"><option value="0">Todos los anuladores</option><?php foreach($listas['usuarios'] as $u):?><option value="<?php echo $u['usuario_id'];?>" <?php echo $filtros['anulador_id']==$u['usuario_id']?'selected':'';?>>Anula: <?php echo html_escape($u['usuario_nombre']);?></option><?php endforeach;?></select> <button class="btn btn-danger"><i class="fa fa-search"></i> Generar</button></form></div></div>
<?php $cant=count($filas);$importe=0;foreach($filas as $x)$importe+=(float)$x['precio'];?>
